const colors = ["red", "green", "blue"];

// for - PELNA kontrola (tu: indeks)
for (let i = 0; i < colors.length; i++) { colors[i]; }

// for...of - WARTOSCI, bez indeksu
for (const color of colors) { color; } // "red", "green", "blue"

// for...in - KLUCZE (dla tablicy: indeksy jako STRINGI - NIEZALECANE dla tablic!)
for (const key in colors) { key; } // "0", "1", "2" (stringi!)

for (let i = 0; i < 5; i++) {
  if (i === 3) continue; // pomin i=3
  if (i === 4) break;    // zatrzymaj PRZED i=4
  console.log(i);
}
// 0, 1, 2 (3 pominiete, 4 nigdy nie osiagniete)

const colors = ["red", "green", "blue"];

for (const [index, color] of colors.entries()) {
  console.log(`${index}: ${color}`);
}
// 0: red
// 1: green
// 2: blue

const liczby = [10, 20, 30];

for (const i in liczby) {
  console.log(i + 1); // BLEDNIE: "01", "11", "21" - i to STRING, nie liczba!
}

const liczby = [10, 20, 30];

for (const [index, wartosc] of liczby.entries()) {
  console.log(index + 1); // POPRAWNIE: 1, 2, 3 - index to LICZBA
}

