const litery = ["a", "b", "c", "d", "e"];
for (let i = 0; i < litery.length; i++) {
  if (i === 2) continue;
  console.log(litery[i]);
}
// a, b, d, e (c pominiete)

const liczby = [1, 2, 3, 4, 5, 6, 7, 8];
for (let i = 0; i < liczby.length; i++) {
  if (liczby[i] > 5) break;
  console.log(liczby[i]);
}
// 1, 2, 3, 4, 5

for (let i = 1; i <= 10; i++) {
  console.log(`5 x ${i} = ${5 * i}`);
}

const litery = ["x", "y", "z"];
for (let i = litery.length - 1; i >= 0; i--) {
  console.log(litery[i]);
}
// z, y, x

const dni = ["poniedzialek", "wtorek", "sroda"];
for (const dzien of dni) {
  console.log(dzien);
}

const liczby = [5, 10, 15];
for (const [indeks, wartosc] of liczby.entries()) {
  console.log(`${indeks}: ${wartosc}`);
}
// 0: 5
// 1: 10
// 2: 15

for (const znak of "Krakow") {
  console.log(znak);
}
// K, r, a, k, o, w

const liczby = [4, 8, 15, 16, 23];
let suma = 0;
for (const n of liczby) {
  suma += n;
}
console.log(suma); // 66

const pary = [[1, "jeden"], [2, "dwa"], [3, "trzy"]];
for (const [numer, slowo] of pary) {
  console.log(`${numer}: ${slowo}`);
}
// 1: jeden
// 2: dwa
// 3: trzy

const osoba = { imie: "Ala", wiek: 30, miasto: "Gdansk" };
for (const klucz in osoba) {
  console.log(`${klucz}: ${osoba[klucz]}`);
}
// imie: Ala
// wiek: 30
// miasto: Gdansk

const osoba = { imie: "Ala", wiek: 30, miasto: "Gdansk" };
for (const klucz in osoba) {
  if (Object.hasOwn(osoba, klucz)) {
    console.log(`${klucz}: ${osoba[klucz]}`);
  }
}

const cennik = { bilet: 20, napoj: 8, popcorn: 15 };
let suma = 0;
for (const klucz in cennik) {
  suma += cennik[klucz];
}
console.log(suma); // 43

const liczby = [10, 20, 30];

for (const i in liczby) {
  console.log(typeof i); // "string" - NIE "number"!
}
// for...in NIE powinno byc uzywane do iteracji po tablicach, poniewaz
// zwraca indeksy jako STRINGI ("0", "1", "2"), nie liczby - proby uzycia
// ich w obliczeniach arytmetycznych (np. i + 1) daja BLEDNE wyniki przez
// konkatenacje tekstu zamiast dodawania. Dodatkowo for...in formalnie NIE
// gwarantuje kolejnosci iteracji. Dla tablic zawsze uzywaj for...of.
